sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (newValue === '') {
        return;
    }

    var outcome = g_form.getValue('u_outcome');
    var collateralTaskType = g_scratchpad.collateral_task_type;
    var managingLocation = g_form.getValue('managing_location').toLowerCase();
    var symphony_chat_room = "";

    var manLocation1 = ['hbeu otc', 'hbeu otc cash', 'hbeu repo'];

    var manLocation2 = ['hbeu otc', 'hbeu otc cash', 'hbeu repo', 'hbap hkh repo', 'hbap reg otc', 'hbap sgh otc', 'hbap sgh repo', 'hbap tky otc', 'hbap mnl otc', 'hbap sel otc', 'hbap bhk otc', 'hbap syd otc', 'hbap syd repo', 'hbau otc', 'hbap hbs otc', 'hbms otc', 'hbap mym otc', 'hase hkh otc', 'hase hkh repo', 'hbfr paris otc', 'hbfr paris repo'];

    var manLocation3 = ['hbap hkh repo', 'hbap reg otc', 'hbap sgh otc', 'hbap sgh repo', 'hbap tky otc', 'hbap mnl otc', 'hbap sel otc', 'hbap bhk otc', 'hbap syd otc', 'hbap syd repo', 'hbau otc', 'hbap hbs otc', 'hbms otc', 'hbap mym otc', 'hase hkh otc', 'hase hkh repo'];

//MSSCOLATRL-402 - changed symphony names for 3 conditions
    if (collateralTaskType == "Base Task" || collateralTaskType == "Symphony API Task 1" ) {
        switch (outcome) {
            case "Action required in Martini - Cancel & Amend":
                if (manLocation1.includes(managingLocation)) {
                    symphony_chat_room = "CSA RECALL REQUESTS";
                }
                break;

            case "Action required in Martini - Unsettle & Amend/Cancel US/EM/AP":
                if (manLocation1.includes(managingLocation)) {
                    symphony_chat_room = "Production - Martini Repo";
                }
                break;

            case "Action required in Martini - Unsettle & Amend/Cancel EU":
                if (manLocation1.includes(managingLocation)) {
                    symphony_chat_room = "Production - Martini Repo";
                }
                break;

            case "Action required in Martini - Unsettle & Amend/Cancel GB":
                if (manLocation1.includes(managingLocation)) {
                    symphony_chat_room = "Production - Martini Repo";
                }
                break;

            case "Action required in Martini - Book/Amend/Cancel":
                if (manLocation1.includes(managingLocation)) {
                    symphony_chat_room = "CSA RECALL REQUESTS";
                }
				else if (manLocation3.includes(managingLocation)) {
                    symphony_chat_room = "HBAP CF";
                }
                break;

			case "Action required in Martini - Unsettle IT":
                if (manLocation2.includes(managingLocation)) {
                    symphony_chat_room = "Production - Martini Repo";
                }
                break;
        }
    } 

	else if (collateralTaskType == "Second Symphony Task" || collateralTaskType == "Symphony API Task 2") {
		switch (outcome) {
            case "Action required in Martini - Cancel & Amend":
            case "Action required in Martini - Unsettle & Amend/Cancel US/EM/AP":
            case "Action required in Martini - Unsettle & Amend/Cancel EU":
            case "Action required in Martini - Unsettle & Amend/Cancel GB":
                if (manLocation1.includes(managingLocation)) {
                    symphony_chat_room = "CSA RECALL REQUESTS";
                }
                break;
        }
    }

	g_form.setValue('u_symphony_chat_room', symphony_chat_room);


}
